        "problem": "// Chapter 5.6 매크로 (선언적 매크로, macro_rules!)\n// 실행: rustc problem.rs -o problem && ./problem\n\n// [문제 1] 가장 단순한 매크로 - 인자 없이 고정 문자열(\"안녕, 매크로!\") 반환\nmacro_rules! greeting {\n    () => {\n        todo!()\n    };\n}\n\n// [문제 2] 인자 하나를 받는 매크로 - 제곱을 계산하는 표현식으로 확장\nmacro_rules! square {\n    ($x:expr) => {\n        todo!()\n    };\n}\n\n// [문제 3] 가변 인자 매크로 - vec! 처럼 여러 개의 값을 받아서 Vec으로 만들기\nmacro_rules! my_vec {\n    ( $( $x:expr ),* ) => {\n        {\n            let mut v = Vec::new();\n            // TODO: $x 들을 순서대로 v에 push\n            v\n        }\n    };\n}\n\n// [문제 4] 여러 패턴을 매칭하는 매크로 - 인자 개수에 따라 다르게 동작(재귀)\nmacro_rules! add_all {\n    () => { 0 };\n    ($x:expr) => { $x };\n    ($x:expr, $($rest:expr),+) => {\n        // TODO: $x 와 나머지(add_all!($($rest),+))를 더해서 반환\n        todo!()\n    };\n}\n\nfn main() {\n    assert_eq!(greeting!(), \"안녕, 매크로!\");\n    println!(\"✅ 문제1 greeting!() 통과\");\n\n    assert_eq!(square!(5), 25);\n    println!(\"✅ 문제2 square!(x) 통과\");\n\n    let v: Vec<i32> = my_vec![1, 2, 3, 4];\n    assert_eq!(v, vec![1, 2, 3, 4]);\n    println!(\"✅ 문제3 my_vec!(가변 인자) 통과\");\n\n    assert_eq!(add_all!(1, 2, 3, 4), 10);\n    assert_eq!(add_all!(), 0);\n    println!(\"✅ 문제4 add_all!(재귀 매크로) 통과\");\n\n    println!(\"🎉 5.6 매크로 챕터 완료!\");\n}\n",
        "answer": "// SOLUTION - 5.6 매크로 (선언적 매크로, macro_rules!)\n\n// [문제 1] 가장 단순한 매크로 - 인자 없이 고정 문자열 반환\nmacro_rules! greeting {\n    () => {\n        \"안녕, 매크로!\".to_string()\n    };\n}\n\n// [문제 2] 인자 하나를 받는 매크로 - 제곱을 계산하는 표현식으로 확장\nmacro_rules! square {\n    ($x:expr) => {\n        $x * $x\n    };\n}\n\n// [문제 3] 가변 인자 매크로 - vec! 처럼 여러 개의 값을 받아서 Vec으로 만들기\nmacro_rules! my_vec {\n    ( $( $x:expr ),* ) => {\n        {\n            let mut v = Vec::new();\n            $( v.push($x); )*\n            v\n        }\n    };\n}\n\n// [문제 4] 여러 패턴을 매칭하는 매크로 - 인자 개수에 따라 다르게 동작\nmacro_rules! add_all {\n    () => { 0 };\n    ($x:expr) => { $x };\n    ($x:expr, $($rest:expr),+) => {\n        $x + add_all!($($rest),+)\n    };\n}\n\nfn main() {\n    assert_eq!(greeting!(), \"안녕, 매크로!\");\n    println!(\"✅ 문제1 greeting!() 통과\");\n\n    assert_eq!(square!(5), 25);\n    println!(\"✅ 문제2 square!(x) 통과\");\n\n    let v: Vec<i32> = my_vec![1, 2, 3, 4];\n    assert_eq!(v, vec![1, 2, 3, 4]);\n    println!(\"✅ 문제3 my_vec!(가변 인자) 통과\");\n\n    assert_eq!(add_all!(1, 2, 3, 4), 10);\n    assert_eq!(add_all!(), 0);\n    println!(\"✅ 문제4 add_all!(재귀 매크로) 통과\");\n\n    println!(\"🎉 5.6 매크로 챕터 완료!\");\n}\n",
